#include "TreesetHeuristic.hpp"

const unsigned int BATCH_SIZE = 16;

void TreesetHeuristic::infer_treeset(RaxmlInstance &instance, const Options &opts, CheckpointManager &cm, LoadBalancer &load_balancer) {
    // generate trees depending on the seed. Note that the normal starting trees are generated by seeding srand() and
    // then generating seeds using rand(), so we won't be creating duplicates by starting over from the random_seed.
    auto seed_offset = opts.random_seed;

    auto batch1 = TunedBatch(true, false, 4, seed_offset, BATCH_SIZE, this->recommended_thread_count(), msa, persite_loglh);
    seed_offset += BATCH_SIZE;
    batch1.infer_batch(instance, opts, load_balancer);

    LOG_INFO_TS << "treeset inference complete." << std::endl;
}

int TreesetHeuristic::recommended_thread_count() {
    // TODO add parameters to options containing the max thread count, which we just assign to the single worker per rank
    return 8;
}

int TreesetHeuristic::recommended_worker_count() {
    // TODO this is only true for the tuning phase
    return 1;
}

unsigned int TunedBatch::get_batch_size() const {
    return this->batch_start_trees->size();
}

void TunedBatch::generate_starting_trees(RaxmlInstance &instance, const Options &opts, LoadBalancer &load_balancer) {
    intVector seeds(this->get_batch_size());
    // generate ascending seeds from a starting point to allow coordinating batch seeds reproducibly.
    std::iota(seeds.begin(), seeds.end(), this->starting_seed);

    auto tree_builder = std::bind(thread_start_trees,
                                  std::ref(instance),
                                  std::ref(*this->batch_start_trees),
                                  StartingTree::parsimony,
                                  std::cref(seeds),
                                  0,
                                  false);

    // infer starting trees
    ParallelContext::init_pthreads_custom(opts, tree_builder, this->num_threads, this->num_threads);
    tree_builder();
    ParallelContext::finalize_threads();

    // load balance using the current thread assignment
    PartitionAssignment part_sizes;

    /* init list of partition sizes */
    size_t i = 0;
    for (auto const& pinfo: this->msa->part_list())
    {
        part_sizes.assign_sites(i, 0, pinfo.length(), pinfo.model().clv_entry_size());
        ++i;
    }

    this->part_assignment.reset(new PartitionAssignmentList(load_balancer.get_all_assignments(part_sizes, num_threads)));
}


void TunedBatch::infer_batch(RaxmlInstance &instance, const Options &opts, LoadBalancer &load_balancer) {
    LOG_INFO_TS << "Running inference batch [BLO: " << !this->light_spr << ", MO: " << !this->skip_model << ", SPR: " <<
            this->num_spr << "] with " << this->num_threads << " threads." << std::endl;

    this->generate_starting_trees(instance, opts, load_balancer);
}
